/* "Latest tax news" block on the home page (index.html and ko/index.html).
 *
 * The block between <!-- latest-news:start --> and <!-- latest-news:end --> is generated from the
 * newest posts in content/blog/<lang>/. It is refreshed by both build tools, in any order:
 *   node tools/build-blog.mjs   (after adding a post)
 *   node tools/build-ko.mjs     (rebuilds ko/index.html from index.html, then puts the Korean block back)
 * Do not edit the block by hand.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const COUNT = 3;
const START = '<!-- latest-news:start';
const END = '<!-- latest-news:end -->';

const L = {
  ko: {
    eyebrow: '세무 소식', heading: '최신 세무 소식', all: '세무 소식 전체 보기', read: '자세히 보기',
    fmt: (d) => { const [y, m, day] = d.split('-').map(Number); return `${y}년 ${m}월 ${day}일`; },
  },
  en: {
    eyebrow: 'Tax News', heading: 'Latest Tax News', all: 'See all tax news', read: 'Read more',
    fmt: (d) => new Date(d + 'T12:00:00Z').toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric', timeZone: 'UTC' }),
  },
};

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function latestPosts(lang) {
  const dir = path.join(ROOT, 'content/blog', lang);
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).filter((f) => f.endsWith('.html')).map((file) => {
    const m = fs.readFileSync(path.join(dir, file), 'utf8').match(/^\s*<!--\s*([\s\S]*?)\s*-->/);
    const meta = m ? JSON.parse(m[1]) : {};
    return { ...meta, slug: file.replace(/\.html$/, '') };
  }).filter((p) => p.title && p.date)
    .sort((a, b) => b.date.localeCompare(a.date) || a.slug.localeCompare(b.slug))
    .slice(0, COUNT);
}

export function latestBlock(lang) {
  const t = L[lang];
  const posts = latestPosts(lang);
  if (!posts.length) return `${START} (generated by tools/blog-latest.mjs) -->\n    ${END}`;
  const items = posts.map((p) => `
          <li>
            <a href="blog/${p.slug}" class="group flex h-full flex-col border border-slate-200 bg-white p-5 transition hover:border-brass">
              <p class="text-[11px] font-bold uppercase tracking-[0.16em] text-brass">${esc(p.category)} · <time datetime="${p.date}" class="normal-case tracking-normal text-slate-500">${t.fmt(p.date)}</time></p>
              <h3 class="mt-2 line-clamp-3 font-semibold leading-snug text-navy group-hover:text-brass-dark">${esc(p.title)}</h3>
              <span class="mt-auto pt-3 text-sm font-semibold text-brass-dark">${t.read} →</span>
            </a>
          </li>`).join('');
  return `${START} (generated by tools/blog-latest.mjs) -->
    <section class="bg-ivory border-b border-slate-200 py-12 sm:py-16" aria-labelledby="latest-news-h">
      <div class="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <div class="flex items-end justify-between gap-4">
          <div>
            <p class="text-xs font-bold uppercase tracking-[0.2em] text-brass">${t.eyebrow}</p>
            <h2 id="latest-news-h" class="mt-2 font-serif text-2xl sm:text-3xl font-semibold text-navy">${t.heading}</h2>
          </div>
          <a href="blog/" class="hidden sm:inline-block shrink-0 text-sm font-semibold text-brass-dark hover:underline">${t.all} →</a>
        </div>
        <ul class="mt-6 grid gap-3 sm:gap-5 md:grid-cols-3">${items}
        </ul>
        <a href="blog/" class="mt-5 flex sm:hidden justify-center border border-navy px-6 py-3 text-sm font-bold text-navy">${t.all} →</a>
      </div>
    </section>
    ${END}`;
}

/** Replace the latest-news block in a home page's HTML. Returns the HTML unchanged if it has no block. */
export function injectLatest(html, lang) {
  const re = /<!-- latest-news:start[\s\S]*?<!-- latest-news:end -->/;
  return re.test(html) ? html.replace(re, () => latestBlock(lang)) : html;
}
